def authorize_tool(user, call):
    risky = call["external_send"] or call["irreversible"] or call.get("cost", 0) > 25
    assert call["name"] in {"create_draft", "publish_lesson"}
    assert user["role"] in call["allowed_roles"]
    if risky:
        assert call.get("human_approval") == "confirmed"
    return {"token_scope": call["name"], "ttl_seconds": 300}
call = {
    "name": "publish_lesson",
    "allowed_roles": ["editor"],
    "external_send": True,
    "irreversible": False,
    "human_approval": "confirmed",
}
print(authorize_tool({"role": "editor"}, call))
